/**
 * 负责四种原有序协议及动态窗口协议的请求绑定与有限运行租约。输入为原请求、机制晚查询和期限别名；
 * 输出为同一 scope 引用和一次完成通知，只写本实例的请求／租约元数据，不写 World、生命或库存。
 * 各实例保独立表及稳定传播回调；同请求可多绑定，但真实窗口只打开对应一个交付 turn。
 * 原 envelope 或领域当前性观察失配永久关闭共同许可；别名自己的字段失配只退役该别名。
 * 合法期限别名共享最早绝对预算，观察到期后时钟回退也不复活。字段 pin 只保顶层原值引用，
 * 不深复制／冻结提示或 feed，不把相同 JSON、readonly 或请求字段当成领域许可。
 * Provider 返回不是付款；窗口完整付款后才 complete，状态先落再通知，晚异常不能二次结算。
 */
import type { ActionRequest } from "./actions";
import { bindRequestDeliveryGuard, registerRequestAliasPropagation, settleRequestDelivery } from "./request-delivery";

/** 仅晚读原 scope 字段／活跃表；不接受整个请求回调，字段接纳与读取次序在本 owner 中实现。 */
export interface RequestLeaseScopeQueries<Owner, Scope> {
  active(owner: Owner): Scope | undefined;
  owner(scope: Scope): Owner;
  actorId(scope: Scope): number;
  phase(): ActionRequest["phase"];
  stage(scope: Scope): ActionRequest["context"]["stage"];
}

/** 动态窗口只给出捕获值和晚领域查询；scope 是每个原请求独立的不透明对象，不由请求重建。
 * 日次／阶段不固定为首夜，明确声明的 context 字段只 pin 原值引用，不创建 World 或死亡许可。
 */
export interface RequestLeaseWindowQueries<Scope extends object> {
  actorId(scope: Scope): number;
  phase(scope: Scope): ActionRequest["phase"];
  day(scope: Scope): number;
  stage(scope: Scope): ActionRequest["context"]["stage"];
  current(scope: Scope): boolean;
}

/** current 仍调用原机制规则；不能据请求字段相同代替原体、生命和库存复验。 */
export interface RequestLeaseCurrentQueries<Owner, Scope> extends RequestLeaseScopeQueries<Owner, Scope> {
  current(scope: Scope): boolean;
}

/** 墙入口先查原作者；原 token／实例值在条件和记录构造位置各自读取，不缓存授权或复制作者。 */
export interface RequestLeaseItemQueries<Owner, Scope, Author> {
  active(owner: Owner): Scope | undefined;
  authors(scope: Scope): Pick<ReadonlyMap<number, Author>, "get">;
  token(scope: Scope): string;
  instanceId(author: Author): string;
  phase(): ActionRequest["phase"];
  stage(): ActionRequest["context"]["stage"];
  current(owner: Owner, scope: Scope, author: Author): boolean;
}

/** context 保原引用，记录不是请求 DTO；合法别名共享同一记录，不做深只读或序列化。 */
interface ScopeBinding<Scope> {
  scope: Scope;
  context: ActionRequest["context"];
}
/** context 身份和声明字段由本 owner 捕获；只保存值／引用，不序列化或深冻结整个 context。 */
interface WindowBinding<Scope> extends ScopeBinding<Scope> {
  fields: Array<{ key: string; value: unknown }>;
}
interface CurrentBinding<Scope> {
  binding: Scope;
  context: ActionRequest["context"];
}
/** 捕获墙的原 owner／作者编号与实例值；后续查询仍晚查活跃墙，不能由编号自行生成许可。 */
interface ItemBinding<Owner, Scope, Author> extends ScopeBinding<Scope> {
  author: Author;
  world: Owner;
  actorId: number;
  instanceId: string;
}

// 字段比较仍排除 deadlineAtMs；其有限未来／只能缩短的政策在比较成功后单独处理。
function sameIndexedFields(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return !(
    keys.length !== other.length ||
    keys.some((k) => !other.includes(k) || (source as any)[k] !== (target as any)[k])
  );
}
function everyIndexedField(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return (
    keys.length === other.length &&
    keys.every((k) => other.includes(k) && (source as any)[k] === (target as any)[k])
  );
}
function everyReflectedField(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return (
    keys.length === other.length &&
    keys.every((k) => other.includes(k) && Reflect.get(source, k) === Reflect.get(target, k))
  );
}

/** 窗口私有的运行完成端口；不持 World/付款回调，不可由 JSON 或请求字段重建。 */
export interface RequestLeaseTurn {
  current(): boolean;
  complete(): void;
  close(): void;
}
/** pin 只核顶层枚举字段及原值引用；嵌套数据/合法 getter/Proxy 不套新 schema 或深只读政策。 */
interface FieldPin { keys: string[]; values: unknown[] }
interface LeaseTurn<Owner, Binding> {
  owner: Owner;
  original: ActionRequest;
  binding: Binding;
  pin?: FieldPin;
  originalDeadline?: unknown;
  deadline: number | null;
  closed: boolean;
  settled: boolean;
  opened: boolean;
  completion: object;
  aliases: Set<ActionRequest>;
  handle?: RequestLeaseTurn;
}
interface LeaseEntry<Owner, Binding> {
  turn: LeaseTurn<Owner, Binding>;
  retired: boolean;
  deadline: unknown;
}
function pinFields(request: ActionRequest): FieldPin {
  const keys = Object.keys(request).filter((key) => key !== "deadlineAtMs");
  return { keys, values: keys.map((key) => Reflect.get(request, key)) };
}
function samePinnedFields(request: ActionRequest, pin: FieldPin): boolean {
  const keys = Object.keys(request).filter((key) => key !== "deadlineAtMs");
  return keys.length === pin.keys.length && keys.every((key) => {
    const index = pin.keys.indexOf(key);
    return index !== -1 && Object.is(Reflect.get(request, key), pin.values[index]);
  });
}

/**
 * 每实例唯一持有请求登记；类型入口开放明确协议，实际机制接线不传完整 request callback。
 * 私有构造签名限制 typed 调用，不是运行时权限屏障；接纳算法在本 owner 内完整执行。
 * 四个旧协议保原字段短路；动态窗口显式增加字段／日次查询，外围复用 F02 政策，不建立 Role 分派或第二租约。
 */
export class RequestLease<Owner, Scope, Binding> {
  private readonly records = new WeakMap<ActionRequest, LeaseEntry<Owner, Binding>>();
  private readonly propagate = (source: ActionRequest, target: ActionRequest): void => {
    this.inherit(source, target);
  };

  private constructor(
    private readonly order: number,
    private readonly bindRequest: (owner: Owner, request: ActionRequest, lease: RequestLease<Owner, Scope, Binding>) => void,
    private readonly matches: (owner: Owner, request: ActionRequest, binding: Binding) => boolean,
    private readonly bindingOwner: (binding: Binding) => Owner,
    private readonly bindingScope: (binding: Binding) => Scope,
    private readonly sameFields: (source: ActionRequest, target: ActionRequest) => boolean,
    private readonly domainCurrent: (owner: Owner, binding: Binding) => boolean,
  ) {}

  /**
   * 动态窗口按 actor→phase→context 身份→day→stage→声明字段核验，末位才调用领域 current。
   * bind 在条件通过后先登记关闭记录，再捕获声明字段和顶层 pin；getter 抛错保该记录关闭，不能重新 bind 复活。
   * contextKeys 的列表副本属于本实例；它不校验深层提示、JSON 或字段类型，也不把这些字段当真实许可。
   */
  static window<Scope extends object>(
    queries: RequestLeaseWindowQueries<Scope>,
    order: number,
    contextKeys: readonly string[] = [],
  ): RequestLease<Scope, Scope, WindowBinding<Scope>> {
    const keys = [...contextKeys];
    return new RequestLease<Scope, Scope, WindowBinding<Scope>>(
      order,
      (scope, request, lease) => {
        if (
          request.actorId === queries.actorId(scope) &&
          request.phase === queries.phase(scope) &&
          request.context.day === queries.day(scope) &&
          request.context.stage === queries.stage(scope)
        ) {
          lease.records.set(request, lease.entry(scope, request, { scope, context: request.context, fields: [] }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          const binding = lease.records.get(request)!.turn.binding;
          for (const key of keys) binding.fields.push({ key, value: Reflect.get(binding.context, key) });
          lease.capture(request);
        }
      },
      (scope, request, binding) =>
        request.actorId === queries.actorId(scope) &&
        request.phase === queries.phase(scope) &&
        request.context === binding.context &&
        request.context.day === queries.day(scope) &&
        request.context.stage === queries.stage(scope) &&
        binding.fields.every(({ key, value }) => Object.is(Reflect.get(request.context, key), value)),
      (binding) => binding.scope,
      (binding) => binding.scope,
      sameIndexedFields,
      (_scope, binding) => queries.current(binding.scope),
    );
  }

  /** actor→phase→day→stage；查询还先核同一活跃 scope，末位晚核机制当前性。 */
  static actorPhaseDayStage<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, ScopeBinding<Scope>> {
    return new RequestLease<Owner, Scope, ScopeBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const scope = queries.active(owner);
        if (
          scope &&
          request.actorId === queries.actorId(scope) &&
          request.phase === queries.phase() &&
          request.context.day === 1 &&
          request.context.stage === queries.stage(scope)
        ) {
          lease.records.set(request, lease.entry(owner, request, { scope, context: request.context }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (owner, request, binding) =>
        queries.owner(binding.scope) === owner &&
        queries.active(owner) === binding.scope &&
        request.actorId === queries.actorId(binding.scope) &&
        request.context === binding.context &&
        request.phase === queries.phase() &&
        request.context.day === 1 &&
        request.context.stage === queries.stage(binding.scope),
      (binding) => queries.owner(binding.scope),
      (binding) => binding.scope,
      sameIndexedFields,
      (_owner, binding) => queries.current(binding.scope),
    );
  }

  /** stage→phase→day→actor→current；查询保原 context→stage→day→phase→current 顺序和 Reflect.get 比较。 */
  static stagePhaseDayActor<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, CurrentBinding<Scope>> {
    return new RequestLease<Owner, Scope, CurrentBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const b = queries.active(owner);
        if (
          b &&
          request.context.stage === queries.stage(b) &&
          request.phase === queries.phase() &&
          request.context.day === 1 &&
          request.actorId === queries.actorId(b) &&
          queries.current(b)
        ) {
          lease.records.set(request, lease.entry(owner, request, { binding: b, context: request.context }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (owner, request, a) =>
        queries.owner(a.binding) === owner &&
        request.actorId === queries.actorId(a.binding) &&
        request.context === a.context &&
        request.context.stage === queries.stage(a.binding) &&
        request.context.day === 1 &&
        request.phase === queries.phase() &&
        queries.current(a.binding),
      (binding) => queries.owner(binding.binding),
      (binding) => binding.binding,
      everyReflectedField,
      () => true, // 原 matches 已在末位调用本族 current，不重复那一次。
    );
  }

  /** actor→phase→stage→day→current；查询的 phase 必须先于 context 身份，不重排成上一种协议。 */
  static actorPhaseStageDay<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, CurrentBinding<Scope>> {
    return new RequestLease<Owner, Scope, CurrentBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const b = queries.active(owner);
        if (
          b &&
          request.actorId === queries.actorId(b) &&
          request.phase === queries.phase() &&
          request.context.stage === queries.stage(b) &&
          request.context.day === 1 &&
          queries.current(b)
        ) {
          lease.records.set(request, lease.entry(owner, request, { binding: b, context: request.context }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (owner, request, a) =>
        queries.owner(a.binding) === owner &&
        request.actorId === queries.actorId(a.binding) &&
        request.phase === queries.phase() &&
        request.context === a.context &&
        request.context.stage === queries.stage(a.binding) &&
        request.context.day === 1 &&
        queries.current(a.binding),
      (binding) => queries.owner(binding.binding),
      (binding) => binding.binding,
      everyIndexedField,
      () => true,
    );
  }

  /** 原物品入口只核 token/instance；phase/day/stage 留在查询，原作者当前性在查询成功后才晚核。 */
  static item<Owner, Scope, Author>(
    queries: RequestLeaseItemQueries<Owner, Scope, Author>,
    order: number,
  ): RequestLease<Owner, Scope, ItemBinding<Owner, Scope, Author>> {
    return new RequestLease<Owner, Scope, ItemBinding<Owner, Scope, Author>>(
      order,
      (world, request, lease) => {
        const a = queries.active(world),
          author = a == null ? undefined : queries.authors(a).get(request.actorId);
        if (
          a &&
          author &&
          request.context.wall_id === queries.token(a) &&
          request.context.item_instance_id === queries.instanceId(author)
        ) {
          lease.records.set(request, lease.entry(world, request, {
            scope: a,
            world,
            actorId: request.actorId,
            instanceId: queries.instanceId(author),
            context: request.context,
            author,
          }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (world, request, binding) =>
        queries.active(world) === binding.scope &&
        request.actorId === binding.actorId &&
        request.context === binding.context &&
        request.context.wall_id === queries.token(binding.scope) &&
        request.context.item_instance_id === binding.instanceId &&
        request.phase === queries.phase() &&
        request.context.day === 1 &&
        request.context.stage === queries.stage(),
      (binding) => binding.world,
      (binding) => binding.scope,
      sameIndexedFields,
      (owner, binding) => queries.current(owner, binding.scope, binding.author),
    );
  }

  /** 条件与 set callee 保原位置；同对象已登记后不得重新 bind 来复活旧 turn。 */
  bind(owner: Owner, request: ActionRequest): void {
    if (this.records.has(request)) return;
    this.bindRequest(owner, request, this);
  }

  /** 只分配运行记录；原 binding/context 已在参数原位置读出。pin 在 set 与传播登记之后才读取。 */
  private entry(owner: Owner, original: ActionRequest, binding: Binding): LeaseEntry<Owner, Binding> {
    return { turn: { owner, original, binding, closed: true, settled: false, opened: false,
      completion: {}, aliases: new Set(), deadline: null }, retired: false, deadline: undefined };
  }

  private capture(request: ActionRequest): void {
    const entry = this.records.get(request)!, turn = entry.turn;
    // 捕获期间先保持关闭：新增 keys/getter 抛错保原已写记录／传播前缀，恢复字段也不重开。
    turn.pin = pinFields(request);
    entry.deadline = request.deadlineAtMs;
    turn.originalDeadline = entry.deadline;
    if (entry.deadline === undefined) turn.closed = false;
    else if (typeof entry.deadline === "number" && Number.isFinite(entry.deadline) && entry.deadline > Date.now()) {
      turn.deadline = entry.deadline;
      turn.closed = false;
    }
  }

  /** 外来 World／未登记请求先拒；alias 自身失配先隔离，不读取或毒化 original。 */
  scope(owner: Owner, request: ActionRequest): Scope | undefined {
    const entry = this.records.get(request);
    if (!entry || entry.turn.owner !== owner || entry.turn.closed || entry.retired) return;
    const turn = entry.turn;
    if (request !== turn.original) {
      try {
        if (!samePinnedFields(request, turn.pin!) || !Object.is(request.deadlineAtMs, entry.deadline)) {
          entry.retired = true;
          return;
        }
      } catch (error) {
        entry.retired = true;
        throw error;
      }
    }
    try {
      // 各协议仍按其声明的 ordered matches 查询 original；共同 context.stage 变坏会关共同 turn。
      if (!this.matches(owner, turn.original, turn.binding) ||
          !samePinnedFields(turn.original, turn.pin!) ||
          !Object.is(turn.original.deadlineAtMs, turn.originalDeadline) ||
          !this.domainCurrent(owner, turn.binding) ||
          (turn.deadline !== null && turn.deadline <= Date.now())) {
        turn.closed = true;
        return;
      }
      return this.bindingScope(turn.binding);
    } catch (error) {
      turn.closed = true;
      throw error;
    }
  }

  /**
   * 真正窗口在 create 后打开交付：各绑定实例不争写 guard。前后登记的 alias 同 guard／completion，
   * 这些引用只留本 owner 的运行集合，不挂 context。每个 Wall request 的 turn 独立于整个墙。
   */
  openDelivery(owner: Owner, request: ActionRequest): RequestLeaseTurn | undefined {
    if (!this.scope(owner, request)) return;
    const turn = this.records.get(request)!.turn;
    if (!turn.handle) turn.handle = {
      current: () => this.scope(owner, request) !== undefined,
      complete: () => this.finish(turn, true),
      close: () => this.finish(turn, false),
    };
    if (!turn.opened) {
      bindRequestDeliveryGuard(turn.original, () => this.scope(owner, turn.original) !== undefined, turn.completion);
      turn.opened = true;
      for (const alias of turn.aliases) this.bindDelivery(turn, alias);
    }
    return turn.handle;
  }

  private bindDelivery(turn: LeaseTurn<Owner, Binding>, request: ActionRequest): void {
    bindRequestDeliveryGuard(request, () => this.scope(turn.owner, request) !== undefined, turn.completion);
  }

  /** 付款结果只由真实窗口给出；不重查已被付款改变的 pending scope。先落终态再发一次通知。 */
  private finish(turn: LeaseTurn<Owner, Binding>, accepted: boolean): void {
    if (turn.settled) return;
    turn.closed = true;
    turn.settled = true;
    turn.aliases.clear();
    settleRequestDelivery(turn.completion, accepted);
  }

  /** 先核来源，再原 ordered fields，最后有限未来期限；坏目标／其 getter 异常不修改来源预算。 */
  private inherit(source: ActionRequest, target: ActionRequest): void {
    const sourceEntry = this.records.get(source);
    if (!sourceEntry || !this.scope(sourceEntry.turn.owner, source) || this.records.has(target)) return;
    if (!this.sameFields(source, target)) return;
    const turn = sourceEntry.turn;
    // 原 === 比较通过后仍须核 F02 pin（含 +0/-0 及晚 getter 原值）；非法目标不得先写记录／缩预算。
    if (!samePinnedFields(target, turn.pin!)) return;
    const deadline = target.deadlineAtMs;
    if (typeof deadline !== "number" || !Number.isFinite(deadline) || deadline <= Date.now() ||
        (turn.deadline !== null && deadline > turn.deadline)) return;
    this.records.set(target, { turn, retired: false, deadline });
    turn.deadline = deadline;
    turn.aliases.add(target);
    registerRequestAliasPropagation(target, this.order, this.propagate);
    if (turn.opened) this.bindDelivery(turn, target);
  }
}

/**
 * 负责请求对象上的交付检查、完成回调和期限别名传播。输入为机制已经绑定的原请求、
 * 当前性查询及不透明完成身份；输出为同步交付检查、一次性结算通知和有序别名绑定。
 * 元数据仅存运行时弱表，不进入模型上下文或归档。机制仍拥有权限、最早期限及单调撤权；
 * 本模块只调用已注册的规则，不以缺少交付检查或相同 JSON 字段判定请求已获授权。
 * 本模块仅写入交付弱表，不修改生命、库存或阶段；结算先删除待通知项再调用回调，异常不恢复。
 * 别名传播遇异常即停止，已完成的绑定不回滚。
 */
import type { ActionRequest } from "./actions";

type AliasPropagation = (original: ActionRequest, alias: ActionRequest) => void;
/** 原请求与别名各自登记元数据；completion 可指向同一机制窗口，不是可序列化许可。 */
interface DeliveryMetadata {
  /** 查询是否可交付；具体原体、生命版本与永久撤权由机制的查询实现负责。 */
  current?: () => boolean;
  /** 将一次 Provider 返回关联到后续领域提交或关闭，不把返回动作当成提交成功。 */
  completion?: object;
  /** 回调身份是键；同一回调重登记只更新顺序，具体别名绑定仍由该机制执行。 */
  aliases?: Map<AliasPropagation, number>;
}

/** 弱表按对象身份关联：复制请求字段不会复制当前性检查或完成身份。 */
const guards = new WeakMap<object, DeliveryMetadata>();
/** 同一完成身份同时最多保留一个待结算回调；原请求和合法别名可共享该身份。 */
const settlements = new WeakMap<object, (accepted: boolean) => void>();
/** 机制成功绑定后登记一次交付检查；保留此前已登记的别名路由。 */
export function bindRequestDeliveryGuard(
  request: object,
  isCurrent: () => boolean,
  completion?: object,
): void {
  const existing = guards.get(request);
  if (existing && "current" in existing)
    throw new Error("action_request_delivery_guard_already_bound");
  guards.set(request, { ...existing, current: isCurrent, completion });
}
/** 无登记时不额外拒绝；有检查时必须严格返回 true，不能用真值替代机制确认。 */
export function assertRequestDelivery(request: ActionRequest): void {
  const guard = guards.get(request);
  if (guard && "current" in guard && guard.current!() !== true)
    throw new Error("action_request_delivery_authority_revoked");
}
/** 登记事务请求的延后通知；无完成身份则返回 false，由调用方执行原有即时通知政策。 */
export function deferRequestDelivery(
  request: ActionRequest,
  settle: (accepted: boolean) => void,
): boolean {
  const completion = guards.get(request)?.completion;
  if (!completion) return false;
  if (settlements.has(completion)) throw new Error("action_request_delivery_already_pending");
  settlements.set(completion, settle);
  return true;
}
export function settleRequestDelivery(completion: object, accepted: boolean): void {
  const settle = settlements.get(completion);
  if (!settle) return;
  // 先消费再通知：重入或回调抛错都不会再次发送同一成功／拒绝通知，也不回滚领域前缀。
  settlements.delete(completion);
  settle(accepted);
}

/** 仅登记已成功绑定的路由；登记自身不会执行回调、校验权限或设置期限。 */
export function registerRequestAliasPropagation(
  request: object,
  order: number,
  inherit: AliasPropagation,
): void {
  let metadata = guards.get(request);
  if (!metadata) {
    metadata = {};
    guards.set(request, metadata);
  }
  (metadata.aliases ??= new Map()).set(inherit, order);
}

/** 机制自行接纳并绑定别名；按顺序调用不等于授予新行动权限。 */
export function inheritRequestAlias(original: ActionRequest, alias: ActionRequest): void {
  const routes = guards.get(original)?.aliases;
  if (!routes) return;
  // 先取路由快照再稳定排序；回调期间增删路由不改变本次名单，抛错时后续路由不执行。
  for (const [inherit] of [...routes].sort((left, right) => left[1] - right[1]))
    inherit(original, alias);
}

/** 调用方先计算最早期限；这里保留原字段展开顺序，再由已登记机制绑定新对象。 */
export function deriveBoundedRequest(original: ActionRequest, deadlineAtMs: number): ActionRequest {
  const alias = { ...original, deadlineAtMs };
  inheritRequestAlias(original, alias);
  return alias;
}

/**
 * 负责实体 ID、组件 Map 与原生命绑定的临时死亡行动许可。输入为既有实体／槽操作及
 * 生命周期回调，输出保持原可写组件引用、筛选结果和许可 ID。World 唯一写入自己的存储，
 * 工厂与角色所有者仍负责值和资源校验；槽推断不增加运行守卫、复制或冻结。
 * 旧任意组件类型 T 重载已退出，读写关系由具名槽约束；死亡许可仍按原生命版本与当前性撤销，ID 本身不授权。
 */
import { EntityId, Phase, Role } from "./model";
import { COMPONENT, ComponentName } from "./components/names";
import type { ComponentMap, ComponentWrite } from "./component-map";
import { AliveComponent, aliveLifeVersion } from "./components/alive";
import { RoleComponent } from "./components/role";
import { isLocale, type Locale } from "@ai-werewolf-arena/game-contract";

/**
 * World 是 ECS 内存状态容器。
 * 设计目标：保持结构简单、读写明确，所有系统都基于该容器进行组件查询与变更。
 */
export class World {
  constructor(readonly locale: Locale = "zh-CN") {
    if (!isLocale(locale)) throw new Error("game_locale_invalid");
  }
  private nextId: EntityId = 1;
  private entities: Set<EntityId> = new Set();
  private stores: Map<ComponentName, Map<EntityId, unknown>> = new Map();
  private nextDeathActionId = 1;
  // 许可绑定原 Alive 对象和该对象的生命版本；复活、替换组件或失去当前性均撤销旧许可。
  private deathActions = new Map<
    EntityId,
    {
      id: number;
      tool: "shoot" | "speak" | "choose_badge_successor";
      phase: Phase;
      day: number;
      abilityId?: string;
      alive: AliveComponent;
      lifeVersion: number;
      isCurrent: () => boolean;
    }
  >();

  /** 引擎拥有的临时行动许可；ID 不授予行动。World 复核原生命与传入的当前性回调，带阶段的查询另核许可记录的 phase／day。 */
  openDeathAction(
    actorId: EntityId,
    tool: "shoot" | "speak" | "choose_badge_successor",
    phase: Phase,
    day: number,
    isCurrent: () => boolean = () => true,
    abilityId?: string,
  ): { readonly id: number; close(): void } {
    if (this.currentDeathAction(actorId)) throw new Error("death_action_already_open");
    const alive = this.getComponent(actorId, COMPONENT.Alive);
    const lifeVersion = alive && aliveLifeVersion(alive);
    if (
      !alive ||
      alive.alive !== false ||
      lifeVersion === undefined ||
      !this.getComponent(actorId, COMPONENT.Role) ||
      !Number.isSafeInteger(day) ||
      day < 1 ||
      !["shoot", "speak", "choose_badge_successor"].includes(tool) ||
      !Object.values(Phase).includes(phase) ||
      phase === Phase.GameOver ||
      (abilityId !== undefined &&
        (tool !== "shoot" ||
          typeof abilityId !== "string" ||
          !/^[a-z][a-z0-9:_-]{0,127}$/.test(abilityId) ||
          abilityId.startsWith("native:")))
    ) {
      throw new Error("death_action_invalid_actor_or_stage");
    }
    const id = this.nextDeathActionId++;
    this.deathActions.set(actorId, {
      id,
      tool,
      phase,
      day,
      abilityId,
      alive,
      lifeVersion,
      isCurrent,
    });
    return Object.freeze({
      id,
      close: () => {
        if (this.deathActions.get(actorId)?.id === id) this.deathActions.delete(actorId);
      },
    });
  }

  hasDeathAction(
    actorId: EntityId,
    tool: string,
    phase: Phase,
    day: number | undefined,
    id: number | undefined,
    abilityId?: string,
  ): boolean {
    const permit = this.currentDeathAction(actorId);
    return (
      permit !== undefined &&
      permit.id === id &&
      permit.tool === tool &&
      permit.phase === phase &&
      permit.day === day &&
      permit.abilityId === abilityId
    );
  }

  isDeathActionOpen(actorId: EntityId, tool: string, id: number, abilityId?: string): boolean {
    const permit = this.currentDeathAction(actorId);
    return (
      permit !== undefined &&
      permit.id === id &&
      permit.tool === tool &&
      permit.abilityId === abilityId
    );
  }

  private currentDeathAction(actorId: EntityId) {
    const permit = this.deathActions.get(actorId);
    if (!permit) return undefined;
    if (
      this.getComponent(actorId, COMPONENT.Alive) !== permit.alive ||
      permit.alive.alive !== false ||
      aliveLifeVersion(permit.alive) !== permit.lifeVersion ||
      !permit.isCurrent()
    ) {
      this.deathActions.delete(actorId);
      return undefined;
    }
    return permit;
  }

  get activeDeathActionCount(): number {
    for (const actorId of this.deathActions.keys()) this.currentDeathAction(actorId);
    return this.deathActions.size;
  }

  closeDeathActions(): void {
    this.deathActions.clear();
  }

  /**
   * 创建新实体并返回实体 ID。
   */
  createEntity(): EntityId {
    const id = this.nextId++;
    this.entities.add(id);
    return id;
  }

  /**
   * 判断实体是否存在。
   */
  hasEntity(entityId: EntityId): boolean {
    return this.entities.has(entityId);
  }

  /**
   * 返回当前所有实体 ID（升序）。
   */
  entityIds(): EntityId[] {
    return [...this.entities].sort((a, b) => a - b);
  }

  addComponent<K extends ComponentName, C extends ComponentWrite<NoInfer<K>>>(
    entityId: EntityId,
    name: K,
    component: C,
  ): void {
    if (!this.hasEntity(entityId)) {
      throw new Error(`Entity ${entityId} does not exist`);
    }

    // 每类组件一张表，按 entityId 索引。
    const store = this.ensureStore(name);
    store.set(entityId, component);
  }

  getComponent<K extends ComponentName>(entityId: EntityId, name: K): ComponentMap[K] | undefined {
    const store = this.stores.get(name);
    return store?.get(entityId) as ComponentMap[K] | undefined;
  }

  /**
   * 从实体上移除指定组件。
   */
  removeComponent(entityId: EntityId, name: ComponentName): void {
    const store = this.stores.get(name);
    store?.delete(entityId);
  }

  /**
   * 返回同时拥有给定组件集合的实体列表。
   */
  entitiesWith(...names: ComponentName[]): EntityId[] {
    // 只有同时拥有所有组件的实体才会被返回，用于系统筛选。
    return this.entityIds().filter((entityId) => {
      return names.every((name) => {
        const store = this.stores.get(name);
        return store?.has(entityId) ?? false;
      });
    });
  }

  /**
   * 返回当前存活实体 ID 列表。
   */
  getAliveEntityIds(): EntityId[] {
    return this.entitiesWith(COMPONENT.Alive).filter((id) => {
      const alive = this.getComponent(id, COMPONENT.Alive);
      return alive?.alive === true;
    });
  }

  /**
   * 按角色筛选实体 ID。
   */
  getEntityIdsByRole(role: Role): EntityId[] {
    return this.entitiesWith(COMPONENT.Role).filter((id) => {
      const roleComp = this.getComponent(id, COMPONENT.Role);
      return roleComp?.role === role;
    });
  }

  /**
   * 确保组件存储存在，不存在则懒加载创建。
   */
  private ensureStore(name: ComponentName): Map<EntityId, unknown> {
    let store = this.stores.get(name);
    if (!store) {
      // 延迟初始化组件存储，避免为未使用组件提前分配空间。
      store = new Map<EntityId, unknown>();
      this.stores.set(name, store);
    }
    return store;
  }
}

/**
 * 负责一局复现请求的开启、结算、事件快照与终结记录；本实例唯一拥有对应轨迹状态。
 * 输入为元数据、原请求、实际 provider 和事件读取回调；输出为经原 schema 2 准入的 Tape 与游标。
 * 结果复制并核对原请求后，在其 delivery scope 登记结算；返回行动可以先于回调，结算回执不表示资源付款。
 * 状态先写入再通知录制器，通知失败不回滚已写前缀；终结保留不完整与 pending 的原拒绝顺序。
 * Node 对象检查仅处理 provider 数据，不进入共享浏览器契约；不控制阶段、持久化文件或复盘版本。
 */
import { types } from "node:util";
import { Camp, type ToolCall } from "@ai-werewolf-arena/game-contract";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import type { ActionRequest } from "@ai-werewolf-arena/game-contract/requests";
import type { ActionProvider } from "../domain/actions";
import { assertRequestDelivery, deferRequestDelivery } from "../domain/request-delivery";
import {
  REPRODUCTION_SCHEMA_VERSION,
  parseReproductionRecord,
  recordedErrorName,
  type RecordedDecision,
  type RecordedCheckpoint,
  type RecordedGameEvent,
  type RecordedErrorName,
  type ReproductionFailureScope,
  type ReproductionMetadata,
  type ReproductionRecord,
} from "./reproduction";


/** deadline 是本轮运行时条件；归档只复制原请求事实，不替换 provider 收到的原对象。 */
export function normalizedRequest(request: ActionRequest): Omit<ActionRequest, "deadlineAtMs"> {
  const { deadlineAtMs: _deadline, ...facts } = request;
  return structuredClone(facts);
}


/** 复制 provider 数据时，不触发 getter、Proxy trap 或自定义序列化。 */
function copyDecisionData(value: unknown, depth = 0): unknown {
  if (
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean" ||
    (typeof value === "number" && Number.isFinite(value))
  )
    return value;
  if (
    !value ||
    typeof value !== "object" ||
    depth > 32 ||
    types.isProxy(value) ||
    Object.getOwnPropertySymbols(value).length
  )
    throw new Error("reproduction_action_not_data");
  const array = Array.isArray(value),
    proto = Object.getPrototypeOf(value);
  if (array ? proto !== Array.prototype : proto !== Object.prototype && proto !== null)
    throw new Error("reproduction_action_not_plain");
  const fields = Object.getOwnPropertyDescriptors(value),
    copy: Record<string, unknown> = {};
  for (const [key, field] of Object.entries(fields)) {
    if (array && key === "length") continue;
    if (!field.enumerable || !Object.hasOwn(field, "value"))
      throw new Error("reproduction_action_accessor");
    Object.defineProperty(copy, key, {
      value: copyDecisionData(field.value, depth + 1),
      enumerable: true,
    });
  }
  if (!array) return copy;
  const length = fields.length?.value;
  if (
    !Number.isSafeInteger(length) ||
    length > 1024 ||
    Object.keys(copy).length !== length ||
    !Array.from({ length }, (_, i) => Object.hasOwn(copy, i)).every(Boolean)
  )
    throw new Error("reproduction_action_array");
  return Array.from({ length }, (_, i) => copy[i]);
}


export class ReproductionTrace {
  // 元数据与七个可变载体共同持有本局因果；事件只在 checkpoint／build 时复制，游标不借用管理器状态。
  private readonly decisions: RecordedDecision[] = [];
  private readonly checkpoints: RecordedCheckpoint[] = [];
  private events: RecordedGameEvent[] = [];
  private settled = 0;
  private invalid = false;
  private readonly errors: Array<{ scope: ReproductionFailureScope; name: RecordedErrorName }> = [];
  private readonly turns = new Map<string, number>();
  constructor(
    private readonly metadata: ReproductionMetadata,
    private readonly onChange: () => void,
    private readonly liveEvents?: () => readonly GameEvent[],
  ) {
    this.metadata = structuredClone(metadata);
  }

  /** 录制协作只复制本实例首次捕获的来源；不重读 caller getter、liveEvents 或返回可写原体。 */
  recordedMetadataIdentity(): Pick<ReproductionMetadata, "engine" | "random" | "ruleset"> {
    return structuredClone({ engine: this.metadata.engine, random: this.metadata.random, ruleset: this.metadata.ruleset });
  }

  get settlementCount(): number {
    return this.settled;
  }
  get decisionCount(): number {
    return this.decisions.length;
  }
  get ownedEventCursor(): number | undefined {
    return this.metadata.normalizedBoard.nobleSecretBody ||
      this.metadata.normalizedBoard.fragrantPairSeer ||
      this.metadata.normalizedBoard.animalDream
      ? (this.liveEvents?.().length ?? this.events.length)
      : undefined;
  }
  async decide(request: ActionRequest, provider: ActionProvider): Promise<ToolCall | null> {
    const key = `${request.actorId}/${request.context.day}/${request.context.stage}`;
    const turn = (this.turns.get(key) ?? 0) + 1;
    this.turns.set(key, turn);
    const entry: RecordedDecision = {
      actorId: request.actorId,
      day: request.context.day,
      stage: request.context.stage,
      turn,
      request: normalizedRequest(request),
      openedAfterSettlement: this.settled,
      ...(this.ownedEventCursor === undefined ? {} : { openedAtEventCount: this.ownedEventCursor }),
      outcome: { kind: "pending" },
    };
    // 开启先提交计数和 pending 前缀；通知抛错时不调用 provider，也不回滚该前缀。
    this.decisions.push(entry);
    this.onChange();
    try {
      const action = await provider.getAction(request);
      const recordedAction = copyDecisionData(action) as ToolCall | null;
      assertRequestDelivery(request);
      // 请求原体的 delivery scope 决定何时结算；正常返回 action 仍可能留下 pending。
      const settle = (accepted: boolean) => {
        entry.outcome = accepted
          ? { kind: "action", action: recordedAction }
          : { kind: "error", code: "decision_failed", name: "Error" };
        entry.settleOrder = ++this.settled;
        this.onChange();
      };
      if (!deferRequestDelivery(request, settle)) settle(true);
      return recordedAction;
    } catch (error) {
      // 同步 settle 的通知也在此 try 内：通知抛错后写 error 并再次增加结算计数，再通知。
      // deferred 回调在未来调用时才执行，异常不会回到本 try；保留原边界与已写前缀。
      // 传输错误文本可能含认证凭证；只保留可复现的失败信息，原始消息不入档。
      entry.outcome = { kind: "error", code: "decision_failed", name: recordedErrorName(error) };
      entry.settleOrder = ++this.settled;
      this.onChange();
      throw error;
    }
  }

  invalidate(): void {
    this.invalid = true;
    this.onChange();
  }

  noteFailure(scope: ReproductionFailureScope, error: unknown): void {
    this.errors.push({ scope, name: recordedErrorName(error) });
    this.onChange();
  }

  checkpoint(checkpoint: RecordedCheckpoint, events: readonly GameEvent[]): void {
    if (events.length !== checkpoint.eventCount)
      throw new Error("reproduction_checkpoint_events_mismatch");
    // 数量不匹配须在任何写入之前拒绝；带机制的 checkpoint 追加当前决定／结算计数。
    this.checkpoints.push(
      structuredClone(
        checkpoint.animalDream || checkpoint.nobleBody || checkpoint.fragrantPair
          ? { ...checkpoint, settlementCount: this.settled, decisionCount: this.decisions.length }
          : checkpoint,
      ),
    );
    this.events = structuredClone(
      events.map(({ payload, ...event }) => ({ ...event, payload: { ...payload } })),
    );
    this.onChange();
  }

  build(input?: {
    operations: ReproductionRecord["operations"];
    termination: { reason: string; winner: Camp | null };
  }): ReproductionRecord {
    const currentEvents = this.liveEvents?.();
    if (currentEvents && currentEvents.length < (this.checkpoints.at(-1)?.eventCount ?? 0))
      throw new Error("reproduction_live_events_before_checkpoint");
    const record = {
      schemaVersion: REPRODUCTION_SCHEMA_VERSION,
      finalized: Boolean(input),
      metadata: this.metadata,
      decisions: this.decisions,
      checkpoints: this.checkpoints,
      events: currentEvents
        ? structuredClone(
            currentEvents.map(({ payload, ...event }) => ({ ...event, payload: { ...payload } })),
          )
        : this.events,
      operations: input?.operations ?? [],
      termination: input ? { ...input.termination, errors: this.errors } : null,
    };
    // 最终拒绝先看失效，再看 pending；错误账本仍按登记顺序输出。
    if (input && this.invalid) throw new Error("reproduction_trace_incomplete");
    if (input && this.decisions.some((entry) => entry.outcome.kind === "pending"))
      throw new Error("reproduction_decisions_pending");
    return parseReproductionRecord(record);
  }
}

/**
 * 负责预言家原生／受赠查验状态的创建、同实例读取与实际报告写入。输入为原角色、
 * 捕获状态及已验证目标／阵营结果；输出保留 lastTarget、lastIsWerewolf、lastResult 与历史
 * 的原有序写入。普通查验消费捕获 state，受赠查验分别读取四次 ability.state 和两次 target.id，
 * 不能缓存或合并为一次写入。JSON 复制不新增 payload 形状校验，native 库存安装归 prepared owner；
 * 目标、次数、生命与请求资格仍归原 caller／lease，政策身份字节不替代档案编码或新授权。
 */
import type { SeerState, SeerReadState } from "@ai-werewolf-arena/game-contract";

import type { EntityId, InspectionResult } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../domain/components/role";
import { copyAbilityData, findNightAbility, type NightAbilityReadView } from "../abilities";
import { commitPreparedNativeAbility } from "../abilities";

/** 安装保留原输入复制与返回 owned 引用；只在初始化入口写原生库存。 */
export function setSeerState(roleComp: RoleComponent, state: SeerState): SeerReadState {
  return commitPreparedNativeAbility(roleComp, "seer_check", SEER_STATE_SLOT.create(state));
}

/** 原生优先选择不按活跃／耗尽过滤；读取不创建或补充资源。 */
export function getSeerState(
  roleComp: RoleComponent,
  abilityId?: string,
): SeerReadState | undefined {
  return findNightAbility(roleComp, "seer_check", abilityId)?.state;
}

/** caller 仍拥有目标／scope 检查及写前、写后的效果；部分失败不回滚前缀。 */
export function recordSeerInspection(
  state: SeerReadState,
  targetId: EntityId,
  isWerewolf: boolean,
  inspection: InspectionResult,
): void {
  (state as SeerState).lastTarget = targetId;
  (state as SeerState).lastIsWerewolf = isWerewolf;
  (state as SeerState).lastResult = { ...inspection };
  (state as SeerState).history.push({ targetId, isWerewolf, result: { ...inspection } });
}

/** 受赠查验保留每次写入前的 state 读取，以及原两次 target.id 读取，不缓存它们。 */
export function recordRecipientSeerInspection(
  ability: NightAbilityReadView<"seer_check">,
  target: { readonly id: EntityId },
  isWerewolf: boolean,
  result: InspectionResult,
): void {
  (ability.state as SeerState).lastTarget = target.id;
  (ability.state as SeerState).lastIsWerewolf = isWerewolf;
  (ability.state as SeerState).lastResult = { ...result };
  (ability.state as SeerState).history.push({
    targetId: target.id,
    isWerewolf,
    result: { ...result },
  });
}

/** 原 JSON callee 先于全部状态字段读取；只迁政策身份字节，不新增 payload snapshot 或失效租约。 */
function encodePolicyIdentity(ability: NightAbilityReadView<"seer_check">): string {
  return JSON.stringify([ability.state.targetPolicy, ability.state.actionPolicy]);
}

/**
 * 本族完整契约引用原 JSON 复制函数和具体有序写入；create／schema 不改变旧接受集合。
 * install／get 与 caller 都消费同一实例库存，metadata 和 lease 保留唯一原所有者。
 * policyIdentity 是旧失效身份字节；checkpoint 归档并不调用新验证或改变原 privateState 形状。
 */
export const SEER_STATE_SLOT = Object.freeze({
  create: copyAbilityData<SeerState>,
  schema: copyAbilityData<SeerState>,
  install: setSeerState,
  get: getSeerState,
  allowedWrites: Object.freeze({
    recordSeerInspection,
    recordRecipientSeerInspection,
  }),
  checkpoint: Object.freeze({ policyIdentity: encodePolicyIdentity }),
  invalidations: Object.freeze({ policyIdentity: encodePolicyIdentity }),
});

/**
 * 负责：顺序执行夜间阶段、收集有来源的效果并准备黎明伤害。
 * 输入：当前 World、真实 RulePlan、阶段贡献和行动提供者；输出：原夜间摘要与死亡提案。
 * 原生策略和具体生命周期单位由同一计划装配；actor、目标、库存和原体资格仍现场查询。
 * 默认阶段固定成员及顺序，注入惰性来源在前一阶段提交后才拉取下一项。
 * 取消检查后，参数仍在首次 acquired 的原 World 参数位置绑定；改变参数不隐式重编译。
 * 来源元数据不授予资格；原 handler receiver 与 execute getter 保持晚读取。
 * 已捕获 day 原值交给伤害折叠，机械／觉醒／原毒 intent 单独保留来源及原体；
 * intent 元数据不进入夜间摘要、事件或 schema2，旧注入 claim 保持兼容。
 * 晚交接保留真实单位的 owned 状态和原失败前缀，result 与最终伤害仍在原已付效果之后准备。
 * 已提交重入准入交有限规则组合，在原婚约开夜之后检查；拒绝不撤销原已付效果，原 finally 仍收尾。
 * 明辉／梦及增益伤害与猎魔来源交付各归具名规则组合；本流水线保封存、伤害结算及死亡生命捕获的原检查点。
 * 运行梦句柄、猎魔 token 与晚保护闭包不进入玩家摘要或归档。
 */
import { attachNightUnit } from "../../../domain/night-unit";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { prepareNightPipelineLifecycle, type NightLifecycleHandoff } from "../../../rulesets/night-lifecycle-plan";


import { assertNightSetupReady, assertNightReadable } from "../../../rulesets/night-readability";
import { RulePlan } from "../../../rulesets/rule-plan";
import { bindNightAbilityActorQuery } from "../../mechanisms/roles/night-ability-actors";
import { isFragrantPairBoard, fragrantAuthoritySnapshot } from "../../mechanisms/roles/fragrant_pair_seer/ports";
import { createNobleNightAbortReceiver, attachNobleNightReceiver, checkpointNobleBodyAuthority, isNobleBodyBoard } from "../../mechanisms/roles/noble_secret_body/ports";
import { animalAuthoritySnapshot } from "../../mechanisms/roles/animal_dream/ports";
import { isRadiantEclipseBoard } from "../../mechanisms/roles/radiant_eclipse/ports";
import { isScholarMentorBoard } from "../../mechanisms/roles/scholar_mentor/ports";
import { mistKnifeTargets, isMistRavenBoard } from "../../mechanisms/roles/mist_raven/ports";
import { assertNightModifierBonusEffects } from "../../../rulesets/night-damage-composition";
import { isTimeConsortBoard } from "../../mechanisms/roles/time_wolf_consort/ports";
import { isMagicianBoard } from "../../mechanisms/roles/magician/ports";
import { isRedMoonBoard } from "../../mechanisms/roles/demon_hunter/ports";
import {
  isNightmareBoard,
